from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
def out(n,v):(R/'data'/n).write_text(json.dumps(v,indent=2))
fia='https://www.fia.com/sites/default/files/fia_2025_formula_1_technical_regulations_-_issue_01_-_2024-12-11_1.pdf'
new='https://www.fia.com/news/new-era-competition-fia-showcases-future-focused-formula-1-regulations-2026-and-beyond'
out('ground_truth_physics.json',{'title':'Formula 1 power unit / 2014–2025 architecture','status':'educational schematic; not homologated CAD or a validated digital twin','sources':{'FIA2025':fia,'FIA2026':new,'Mercedes':'https://www.mercedesamgf1.com/team/location/brixworth'},'published_facts':{'displacement':{'value':0.0016,'unit':'m^3','source':'FIA2025 Article 5.2'},'cylinders':{'value':6,'source':'FIA2025 Article 5.2'},'bank_angle':{'value':90,'unit':'degrees','source':'FIA2025 Article 5.2'},'mgu_k_power_limit':{'value':120000,'unit':'W','source':'FIA2025 Article 5.3.3'},'k_to_store_per_lap':{'value':2000000,'unit':'J','source':'FIA2025 Article 5.3.2 energy flow diagram'},'store_to_k_per_lap':{'value':4000000,'unit':'J','source':'FIA2025 Article 5.3.2 energy flow diagram'},'thermal_efficiency':{'value':'>50%','source':'Mercedes','scope':'manufacturer claim; not all operating points or all teams'},'2026':{'value':'MGU-H removed; MGU-K maximum increased to 350 kW','source':'FIA2026'}},'design_inputs':{'chapters':{'value':['Assembly','Reveal','V6 ICE','MGU-H','MGU-K','Energy store'],'source':'user brief'},'duration':{'value':120,'unit':'s','source':'invoked skill default'}},'modeling':{'dimensions':{'value':[5.5,2.0,1.1],'unit':'m','assumption':'schematic vehicle envelope, not a team car'},'mass':{'value':800,'unit':'kg','assumption':'illustrative vehicle bookkeeping only'},'mass_distribution':{'value':[0.46,0.54],'unit':'front/rear fractions','assumption':'unused by energy model'},'center_of_mass':{'value':[0,0,0.35],'unit':'m','assumption':'unused by kinematic reveal'},'gravity':{'value':[0,0,-9.81],'unit':'m/s^2','assumption':'scene convention; no free-body integration'},'contact_friction':{'value':0,'assumption':'no contact dynamics; articulated schematic with deliberately overlapping visual housings'},'solver_rate':{'value':120,'unit':'Hz','assumption':'energy ledger integration'},'collision_tolerance':{'value':0.001,'unit':'m','assumption':'disjoint internal test proxies only, not visual housing clearance'},'initial_conditions':{'value':{'store_J':2000000,'recovered_J':0,'deployed_J':0},'assumption':'illustrative cycle'},'efficiency':{'value':0.95,'assumption':'constant bidirectional K conversion; not measured'},'coordinate_convention':{'value':'Blender +Z up, +X longitudinal; glTF exports +Y up (x,y,z -> x,z,-y)','assumption':'project convention'},'motion':{'value':'quintic smoothstep keyframed editorial transforms','assumption':'not an explosion dynamics simulation'},'uncertainty':{'value':'geometry, component masses, packaging, losses and operating schedule illustrative; no team telemetry','assumption':'no proprietary inputs available'},'known_failure_modes':{'value':['constant efficiencies omit temperature and RPM effects','energy schedule is not a racing lap','schematic surfaces intersect at assembly interfaces','motion is slowed and separated for readability'],'assumption':'model scope'}},'validation_results':{'derived_from':'data/validation.json'}})
out('academic_citations.json',[{'title':'Optimal control of Formula One car energy recovery systems','authors':['David J. N. Limebeer','Giacomo Perantoni','Anil V. Rao'],'year':2014,'venue':'International Journal of Control, 87(10)','doi':'10.1080/00207179.2014.900705','url':'https://www.anilvrao.com/Publications/JournalPublications/F-1-Optimal-Control-Energy-Recovery.pdf','relevance':'context for coupled kinetic and thermal ERS energy management; our ledger does not reproduce its optimal-control model','access':'bibliographic record and abstract consulted; not full validation basis'}])
out('milestone_history.json',[{'year':2014,'event':'1.6 L V6 turbo hybrid architecture with MGU-K and MGU-H introduced','source':'https://www.formula1.com/en/latest/article/a-racing-revolution-understanding-2014s-technical-regulations.1bTbN3OAEksY00PVE62KvC'},{'year':2025,'event':'Final season of this MGU-H architecture','source':new},{'year':2026,'event':'MGU-H removed; maximum MGU-K power rises to 350 kW','source':new}])
assert all(x.get('source') for x in json.loads((R/'data/milestone_history.json').read_text()))
print('Research gate passed: sourced facts separated from design assumptions')

# Preserve detailed-exterior provenance when regenerating the research record.
p=R/"data/ground_truth_physics.json"
j=json.loads(p.read_text())
j["exterior_provenance"]={"source":"https://sketchfab.com/3d-models/oracle-red-bull-f1-car-rb19-2023-e4afe46f3aab4b23a418da06fc163821","author":"Redgrund","license":"CC BY 4.0","assumption":"artistic exterior uniformly normalized to 2m width; not certified 1:1 team CAD"}
